#include "tapesister/ts_app.h"
#include <stdio.h>
#include <threads.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"FAIL %d %s\n",__LINE__,#x);return 1;}}while(0)
static bool wait_preview(ts_app_state*a){for(unsigned i=0;i<1000000;i++){ts_app_poll_render(a);if(ts_app_render_matched(a))return true;thrd_yield();}return false;}
int main(void){ts_app_state app;char error[256]={0};CHECK(ts_app_load_bank(&app,TS_FIXTURE_DIR,NULL,error,sizeof error));uint64_t navigation_generation=app.working_generation;CHECK(ts_app_page_move(&app,1)&&app.page==TS_PAGE_CONTOUR);CHECK(ts_app_page_move(&app,-1)&&app.page==TS_PAGE_SOURCE);int first=app.focused_parameter;CHECK(ts_app_focus_move(&app,1)&&app.focused_parameter!=first);CHECK(ts_parameter_by_id((ts_parameter_id)app.focused_parameter)->page==TS_PAGE_SOURCE);CHECK(app.working_generation==navigation_generation&&app.selected==0);CHECK(!ts_app_session_requires_discard(&app));CHECK(ts_app_select_recipe_confirmed(&app,1,false));CHECK(!ts_app_session_requires_discard(&app));CHECK(ts_app_select_recipe_confirmed(&app,0,false));CHECK(ts_app_request_render(&app));CHECK(wait_preview(&app));const ts_audition_source*a_source=ts_app_preview_source(&app);CHECK(a_source);ts_audition_mixer mixer;CHECK(ts_audition_init(&mixer,48000));CHECK(ts_audition_note_on(&mixer,a_source,60));uint64_t a_identity=ts_recipe_identity(&app.bank[0].recipe);CHECK(ts_app_adjust_parameter(&app,TS_P_HARMONIC_MIX,1,true));CHECK(app.history.undo_count==1);CHECK(ts_app_session_requires_discard(&app));CHECK(!ts_app_select_recipe_confirmed(&app,1,false));CHECK(app.selected==0&&app.history.undo_count==1);CHECK(!ts_app_select_recipe(&app,app.bank_count));CHECK(app.selected==0&&app.history.undo_count==1);CHECK(ts_app_select_recipe_confirmed(&app,1,true));uint64_t b_identity=ts_recipe_identity(&app.bank[1].recipe);CHECK(b_identity!=a_identity);CHECK(app.history.undo_count==0&&app.history.redo_count==0);CHECK(!ts_app_undo(&app)&&!ts_app_redo(&app));CHECK(ts_recipe_identity(&app.bank[app.selected].recipe)==b_identity);CHECK(ts_app_preview_source(&app)==NULL);CHECK(mixer.voices[0].source==a_source);CHECK(wait_preview(&app));CHECK(ts_app_preview_source(&app)&&app.previews.current->recipe_identity==b_identity);CHECK(ts_app_select_recipe(&app,2));CHECK(ts_app_select_recipe(&app,3));CHECK(ts_app_preview_source(&app)==NULL);CHECK(wait_preview(&app));CHECK(app.previews.current->recipe_identity==ts_recipe_identity(&app.bank[3].recipe));ts_audition_discard_all(&mixer);ts_app_dispose(&app);puts("session boundary tests passed");return 0;}
